const okT = (o) => uniq(o) && o.filter((x) => x.correct).length === 1;
const okN = (o) => okT(o) && o.every((x) => Number.isFinite(x.num)) && uniqNum(o);
/** Bruch als Formel, gekürzt; ganze Zahlen ohne Bruchstrich. */
